func TestE6Exp(t *testing.T) {
	parameters := gopter.DefaultTestParameters()
	parameters.MinSuccessfulTests = 100

	properties := gopter.NewProperties(parameters)
	genA := genE6()

	properties.Property("[babybear] Exp(x, 0) should return one", prop.ForAll(
		func(a E6) bool {
			var res E6
			var one E6
			one.SetOne()
			res.Exp(a, big.NewInt(0))
			return res.Equal(&one)
		},
		genA,
	))

	properties.Property("[babybear] Exp(x, 1) should return x", prop.ForAll(
		func(a E6) bool {
			var res E6
			res.Exp(a, big.NewInt(1))
			return res.Equal(&a)
		},
		genA,
	))

	properties.Property("[babybear] Exp(x, 2) should return x squared", prop.ForAll(
		func(a E6) bool {
			var res, sq E6
			res.Exp(a, big.NewInt(2))
			sq.Square(&a)
			return res.Equal(&sq)
		},
		genA,
	))

	properties.Property("[babybear] Exp(x, k) should match repeated multiplication", prop.ForAll(
		func(a E6) bool {
			var res, mul E6
			k := int64(0b101101) // 45
			res.Exp(a, big.NewInt(k))
			mul.SetOne()
			for i := int64(0); i < k; i++ {
				mul.Mul(&mul, &a)
			}
			return res.Equal(&mul)
		},
		genA,
	))

	properties.Property("[babybear] Exp(x, -k) should equal Exp(x⁻¹, k)", prop.ForAll(
		func(a E6) bool {
			var res, expected, inv E6
			k := int64(0b1011010110110101) // arbitrary positive
			kNeg := new(big.Int).Neg(big.NewInt(k))
			res.Exp(a, kNeg)
			inv.Inverse(&a)
			expected.Exp(inv, big.NewInt(k))
			return res.Equal(&expected)
		},
		genA,
	))

	properties.Property("[babybear] Exp(x, k) for k > int64 should split as Exp(x, k_hi)*Exp(x, k_lo)", prop.ForAll(
		func(a E6) bool {
			// k = 2^65 + 1 = (2^65) + 1, exercises the non-IsInt64 path.
			k := new(big.Int).Lsh(big.NewInt(1), 65)
			k.Add(k, big.NewInt(1))

			var res E6
			res.Exp(a, k)

			// expected = x^(2^65) * x = ((x²)^64)^... — compute via 65 squarings
			var expected E6
			expected.Set(&a)
			for i := 0; i < 65; i++ {
				expected.Square(&expected)
			}
			expected.Mul(&expected, &a)
			return res.Equal(&expected)
		},
		genA,
	))

	properties.TestingRun(t, gopter.ConsoleReporter(false))
}

